// Bird's-eye floor layout: the room from above, with objects, the route, and where you are.
// Generated from the scan, not surveyed, and it says so on screen.

const PADDING = 16;
const TYPE_COLORS = {
  tank: "#f97316",
  pump: "#ef4444",
  motor: "#a855f7",
  valve: "#eab308",
  "electrical cabinet": "#22c55e",
  "control panel": "#22c55e",
  cart: "#38bdf8",
  chair: "#38bdf8",
  ladder: "#38bdf8",
  box: "#94a3b8",
  bucket: "#94a3b8",
  bag: "#94a3b8",
};
const LEGEND = [
  ["Faulty device", "#ff2d2d"],
  ["Linked to a record", "#ffffff"],
  ["Tank", TYPE_COLORS.tank],
  ["Pump", TYPE_COLORS.pump],
  ["Motor", TYPE_COLORS.motor],
  ["Valve", TYPE_COLORS.valve],
  ["Cabinet or panel", TYPE_COLORS["control panel"]],
  ["Can move", TYPE_COLORS.cart],
  ["Other", "#64748b"],
];
const HIDDEN_UNLESS_ASKED = new Set(["pipe", "pipe fitting", "cable", "hose", "light fixture"]);
const FAULT_COLOR = "#ff2d2d";
const ROUTE_COLOR = "#22d3ee";

export function setupPlan({ ui, objects, root, camera, route, getFaultTag, getSelected, onSelect }) {
  const context = ui.canvas.getContext("2d");
  const image = new Image();
  const state = { open: false, ready: false, description: null, showPipes: false, found: null };

  function fit() {
    const box = ui.canvas.getBoundingClientRect();
    const ratio = window.devicePixelRatio || 1;
    ui.canvas.width = box.width * ratio;
    ui.canvas.height = box.height * ratio;
    const d = state.description;
    const scale = Math.min(
      (box.width - 2 * PADDING) / (d.x_max - d.x_min),
      (box.height - 2 * PADDING) / (d.z_max - d.z_min),
    );
    const left = (box.width - scale * (d.x_max - d.x_min)) / 2;
    const top = (box.height - scale * (d.z_max - d.z_min)) / 2;
    return { scale, left, top, ratio };
  }

  // +z points up the page, the way the scan's start view faces.
  function toScreen(view, x, z) {
    const d = state.description;
    return [view.left + (x - d.x_min) * view.scale, view.top + (d.z_max - z) * view.scale];
  }

  function colorOf(object) {
    if (object.asset.mapping?.tag === getFaultTag()) return FAULT_COLOR;
    if (object.asset.mapping) return "#ffffff";
    if (object.asset.mobility === "movable") return TYPE_COLORS.cart;
    return TYPE_COLORS[object.asset.label] ?? "#64748b";
  }

  function footprint(object) {
    const a = object.asset;
    const halfX = Math.abs(a.bbox_max[0] - a.bbox_min[0]) / 2;
    const halfZ = Math.abs(a.bbox_max[2] - a.bbox_min[2]) / 2;
    return { x: object.center.x, z: object.center.z, halfX, halfZ };
  }

  function shown(object) {
    if (object.gone) return false;
    if (object === getSelected() || object === state.found || object.asset.mapping) return true;
    return state.showPipes || !HIDDEN_UNLESS_ASKED.has(object.asset.label);
  }

  function nameOf(object) {
    const link = object.asset.mapping;
    if (!link) return object.asset.label;
    return link.method?.startsWith("procedural") ? `${link.tag}?` : link.tag;
  }

  function draw() {
    if (!state.open || !state.ready) return;
    const view = fit();
    const c = context;
    c.setTransform(view.ratio, 0, 0, view.ratio, 0, 0);
    c.clearRect(0, 0, ui.canvas.width, ui.canvas.height);
    const d = state.description;
    c.drawImage(
      image,
      view.left,
      view.top,
      (d.x_max - d.x_min) * view.scale,
      (d.z_max - d.z_min) * view.scale,
    );

    for (const wall of d.walls) {
      c.beginPath();
      c.setLineDash(wall.assumed ? [8, 6] : []);
      c.strokeStyle = wall.assumed ? "#f87171" : "#f8fafc";
      c.lineWidth = 3;
      c.moveTo(...toScreen(view, ...wall.start));
      c.lineTo(...toScreen(view, ...wall.end));
      c.stroke();
    }
    c.setLineDash([]);

    const labels = [];
    for (const object of objects) {
      if (!shown(object)) continue;
      const f = footprint(object);
      const [x0, y0] = toScreen(view, f.x - f.halfX, f.z + f.halfZ);
      const width = 2 * f.halfX * view.scale;
      const height = 2 * f.halfZ * view.scale;
      const color = colorOf(object);
      const highlighted = object === getSelected() || object === state.found;
      c.fillStyle = `${color}33`;
      c.fillRect(x0, y0, width, height);
      c.strokeStyle = highlighted ? "#facc15" : color;
      c.lineWidth = highlighted || color === FAULT_COLOR ? 3 : 1.5;
      c.strokeRect(x0, y0, width, height);
      if (object.asset.mapping || highlighted) {
        labels.push({ text: nameOf(object), x: x0 + width / 2, y: y0, color, highlighted });
      }
    }

    const path = route.state.route?.path;
    if (path?.length) {
      c.beginPath();
      c.strokeStyle = ROUTE_COLOR;
      c.lineWidth = 4;
      path.forEach((point, index) => {
        const [x, y] = toScreen(view, point[0], point[2]);
        if (index) c.lineTo(x, y);
        else c.moveTo(x, y);
      });
      c.stroke();
    }

    c.font = "12px system-ui, sans-serif";
    c.textAlign = "center";
    // Important names go last, so that they sit on top.
    labels.sort((a, b) => Number(a.highlighted) - Number(b.highlighted));
    for (const label of labels) {
      const width = c.measureText(label.text).width + 8;
      c.fillStyle = "rgba(15, 20, 25, 0.85)";
      c.fillRect(label.x - width / 2, label.y - 18, width, 16);
      c.fillStyle = label.color;
      c.fillText(label.text, label.x, label.y - 6);
    }

    // Where you are, and which way you face.
    const here = root.worldToLocal(camera.position.clone());
    const ahead = root.worldToLocal(camera.position.clone().add(camera.getWorldDirection(here.clone())));
    const [hx, hy] = toScreen(view, here.x, here.z);
    const [ax, ay] = toScreen(view, ahead.x, ahead.z);
    const angle = Math.atan2(ay - hy, ax - hx);
    c.save();
    c.translate(hx, hy);
    c.rotate(angle);
    c.beginPath();
    c.moveTo(14, 0);
    c.lineTo(-8, -8);
    c.lineTo(-4, 0);
    c.lineTo(-8, 8);
    c.closePath();
    c.fillStyle = "#22d3ee";
    c.strokeStyle = "#0f1419";
    c.lineWidth = 2;
    c.fill();
    c.stroke();
    c.restore();

    // Scale bar: one metre, in the scan's own units.
    const barX = view.left + 12;
    const barY = view.top + (d.z_max - d.z_min) * view.scale - 14;
    c.strokeStyle = "#f8fafc";
    c.lineWidth = 3;
    c.beginPath();
    c.moveTo(barX, barY);
    c.lineTo(barX + view.scale, barY);
    c.stroke();
    c.fillStyle = "#f8fafc";
    c.textAlign = "left";
    c.fillText("1 m (scan's scale)", barX, barY - 6);
  }

  function objectAt(view, sx, sy) {
    let best = null;
    let bestArea = Infinity;
    for (const object of objects) {
      if (!shown(object)) continue;
      const f = footprint(object);
      const [x0, y0] = toScreen(view, f.x - f.halfX, f.z + f.halfZ);
      const width = 2 * f.halfX * view.scale;
      const height = 2 * f.halfZ * view.scale;
      const near = 6; // pixels of tolerance, for small objects under a finger
      const inside =
        sx >= x0 - near && sx <= x0 + width + near && sy >= y0 - near && sy <= y0 + height + near;
      if (inside && width * height < bestArea) {
        best = object;
        bestArea = width * height;
      }
    }
    return best;
  }

  ui.canvas.addEventListener("click", (event) => {
    if (!state.ready) return;
    const box = ui.canvas.getBoundingClientRect();
    const found = objectAt(fit(), event.clientX - box.left, event.clientY - box.top);
    if (found) {
      state.found = null;
      onSelect(found);
    }
  });

  function search(text) {
    const wanted = text.trim().toLowerCase();
    state.found = null;
    ui.note.textContent = "";
    if (!wanted) return;
    const matches = objects.filter((object) => {
      const tag = object.asset.mapping?.tag?.toLowerCase() ?? "";
      const id = object.asset.object_id.toLowerCase();
      return !object.gone && (tag === wanted || id === wanted || tag.includes(wanted));
    });
    const byLabel = objects.filter((o) => !o.gone && o.asset.label?.toLowerCase() === wanted);
    state.found = matches[0] ?? byLabel[0] ?? null;
    const total = matches.length || byLabel.length;
    ui.note.textContent = state.found
      ? `Found ${total}: showing ${nameOf(state.found)}`
      : "Nothing with that tag or type";
  }
  ui.search.addEventListener("input", () => search(ui.search.value));

  ui.pipes.onclick = () => {
    state.showPipes = !state.showPipes;
    ui.pipes.textContent = state.showPipes ? "Hide pipes" : "Show pipes";
  };

  for (const [name, color] of LEGEND) {
    const item = document.createElement("span");
    const swatch = document.createElement("i");
    swatch.style.background = color;
    item.append(swatch, name);
    ui.legend.append(item);
  }

  async function open() {
    state.open = true;
    ui.panel.hidden = false;
    if (state.ready) return;
    ui.note.textContent = "Building the layout...";
    try {
      const response = await fetch("/api/plan");
      const reply = await response.json();
      if (!response.ok) throw new Error(reply.detail ?? `Backend error ${response.status}`);
      state.description = reply;
      image.src = "/api/plan/floor.png";
      await image.decode();
      state.ready = true;
      ui.note.textContent = "";
    } catch (error) {
      ui.note.textContent = `Couldn't build the layout: ${error.message}`;
    }
  }

  function close() {
    state.open = false;
    ui.panel.hidden = true;
  }

  return { state, open, close, draw, search };
}

